#!/bin/bash
# Rebin assessment follow-up (the director's request, 2026-11-10): do the pscratch inputs a merge-only rebin would need
# still exist? STAT ONLY: each file below is stat()ed once (size and atime), which reads no file's contents and lists no
# directory. Nothing is written on the cluster; the report goes to stdout. Launched from a /dev/shm copy of itself
# (its path is $1), which it deletes at exit. The list is built from committed records only (make_lists.py at 58719d4b):
#   central   s5p-20260926 data_b-_j-.npz (fb5cc679, the data central value)
#   cstat     s5p-20260926 data_b21..50_j121..150 (C_stat's replicas not committed; S1-REPORT.md:222-225)
#   f0b_*     F0b's inputs by its own selection (fd_f0_regrade.py:560-584) on the committed manifests named in
#             fd_f0b_readout.json's argv: graded (221 experiments of the 12 graded truths, incl. closure_nuwro),
#             floor (1), pow (1,147, the ungraded P rows), cal (7,176, the A7 offset control, :738-775)
#   prr       FD-PRR's 181 route-1 products (fd/receipts-prr/misc/cluster/log-misc/SHA256SUMS)
#   cpl       C_PL,5D's 34 period unfolds and 4 MC truths (fd_ct_5b_periods.json inputs_sha256; 5b-inputs-steps.tsv)
SELF=$1
echo "node $(hostname) $(date -u +%FT%TZ)"
echo "script sha256 $(sha256sum "$SELF" | cut -d' ' -f1)"
now=$(date +%s)
awk -v now="$now" '
function flush() {}
{ g=$1; p=$2; n[g]++
  cmd = "stat -c \"%s %X\" -- \"" p "\" 2>/dev/null"; line=""; cmd | getline line; close(cmd)
  if (line == "") { miss[g]++; if (nm[g] < 5) { nm[g]++; ex[g] = ex[g] "\n    missing: " p } }
  else { split(line, a, " "); have[g]++; bytes[g] += a[1]; age=(now - a[2]) / 86400.0
         if (!(g in oldest) || age > oldest[g]) oldest[g] = age; if (!(g in newest) || age < newest[g]) newest[g] = age } }
END { printf "%-11s %6s %6s %6s %14s %10s %10s\n", "group", "listed", "found", "missing", "bytes found", "atime max d", "atime min d"
      for (g in n) printf "%-11s %6d %6d %6d %14d %10.1f %10.1f%s\n", g, n[g], have[g]+0, miss[g]+0, bytes[g]+0, oldest[g]+0, newest[g]+0, ex[g] }
' <<'LIST'
